    'ORGANIZATION': 'ORG',
    'ORGANISATION': 'ORG',
    'LOCATION': 'LOC',
    'NUMBER': 'NUM',
    'NUMERICAL': 'NUM',
    'MISCELLANEOUS': 'MISC',
}


def normalize_entity_type(raw_type):
    """Strip whitespace, uppercase, and apply alias mapping."""
    t = raw_type.strip().upper()
    return ENTITY_TYPE_ALIASES.get(t, t)



def _levenshtein(s1, s2):
    if len(s1) < len(s2):
        return _levenshtein(s2, s1)
    if len(s2) == 0:
        return len(s1)
    prev_row = range(len(s2) + 1)
    for i, c1 in enumerate(s1):
        curr_row = [i + 1]
        for j, c2 in enumerate(s2):
            insertions = prev_row[j + 1] + 1
            deletions = curr_row[j] + 1
            substitutions = prev_row[j] + (c1 != c2)
            curr_row.append(min(insertions, deletions, substitutions))
        prev_row = curr_row
    return prev_row[-1]


def load_constraints(path: str) -> dict:
    with open(path) as f:
        return json.load(f)


def build_relation_name_to_id(rel_types: dict) -> dict:
    """Map relation name -> relation ID for matching model output."""
